// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 val1, uint256 val2) public {
        vm.assume(val1 != val2);

        // Before initialization SetMinSum is allowed to set MinSum.
        c.SetMinSum(val1);
        assertEq(c.MinSum(), val1);

        c.Initialized();

        // RULE: after initialization, a SetMinSum call must not change MinSum
        // (in the reference it reverts; MinSum stays val1).
        bool ok;
        try c.SetMinSum(val2) { ok = true; } catch { ok = false; }

        assertTrue((!ok && c.MinSum() == val1) || (ok && c.MinSum() == val1));
    }
}
